{"content": "#!/usr/bin/env python3
"""
Live Session Monitor for BrowserOS neo
Records browser activity in real-time from user browsing sessions
Connects to BrowserOS neo MCP at http://127.0.0.1:9020/mcp
"""
import json
import time
import asyncio
import requests
from datetime import datetime
from pathlib import Path
from typing import Optional

BROWSEROS_URL = "http://127.0.0.1:9020"
SESSIONS_DIR = Path("H:/session-records")
SESSIONS_DIR.mkdir(parents=True, exist_ok=True)

class LiveMonitor:
    """Monitor BrowserOS neo and record interactions"""

    def __init__(self):
        self.sessions = {}
        self.current_site = None
        self.api_key = None  # Will be read from env or config

    def get_browser_status(self) -> dict:
        """Check BrowserOS neo health"""
        try:
            resp = requests.get(f"{BROWSEROS_URL}/health", timeout=5)
            return resp.json() if resp.status_code == 200 else {}
        except Exception as e:
            return {"error": str(e)}

    def record_site_start(self, site_name: str, url: str) -> str:
        """Start recording a new site session"""
        session_id = f"{site_name}_{datetime.now().strftime('%Y%m%d_%H%M%S')}"
        self.sessions[session_id] = {
            "site_name": site_name,
            "url": url,
            "start_url": url,
            "started": datetime.now().isoformat(),
            "interactions": [],
            "page_snapshots": [],
            "url_history": [url],
            "clicks": [],
            "forms": [],
            "framework": None,
            "bot_protection": None
        }
        self.current_site = session_id
        print(f"[RECORDING] {site_name}: {url}")
        return session_id

    def record_click(self, element_info: dict):
        """Record a click interaction"""
        if not self.current_site:
            return
        self.sessions[self.current_site]["interactions"].append({
            "type": "click",
            "element": element_info,
            "timestamp": datetime.now().isoformat()
        })
        self.sessions[self.current_site]["clicks"].append(element_info)

    def record_navigation(self, url: str):
        """Record page navigation"""
        if not self.current_site:
            return
        self.sessions[self.current_site]["interactions"].append({
            "type": "navigation",
            "url": url,
            "timestamp": datetime.now().isoformat()
        })
        self.sessions[self.current_site]["url_history"].append(url)

    def record_type(self, field_name: str, field_type: str, value_length: int, selector: str = None):
        """Record text input"""
        if not self.current_site:
            return
        self.sessions[self.current_site]["interactions"].append({
            "type": "type",
            "field": field_name,
            "field_type": field_type,
            "value_length": value_length,
            "selector": selector,
            "timestamp": datetime.now().isoformat()
        })

    def record_form_submission(self, form_selector: str = None):
        """Record form submission"""
        if not self.current_site:
            return
        self.sessions[self.current_site]["interactions"].append({
            "type": "form_submit",
            "form_selector": form_selector,
            "timestamp": datetime.now().isoformat()
        })

    def save_session(self, session_id: str) -> Optional[str]:
        """Save session to disk"""
        if session_id not in self.sessions:
            return None

        filepath = SESSIONS_DIR / f"{session_id}.json"
        with open(filepath, 'w', encoding='utf-8') as f:
            json.dump(self.sessions[session_id], f, indent=2)

        print(f"[SAVED] {filepath}")
        return str(filepath)

    def analyze_session(self, session_id: str) -> dict:
        """Extract patterns from recorded session"""
        if session_id not in self.sessions:
            return {}

        session = self.sessions[session_id]
        analysis = {
            "site_name": session["site_name"],
            "total_interactions": len(session["interactions"]),
            "total_clicks": len(session["clicks"]),
            "navigation_count": len(session["url_history"]) - 1,
            "unique_urls": list(dict.fromkeys(session["url_history"])),
            "interaction_types": {},
            "common_selectors": [],
            "framework_hints": [],
            "bot_protection_detected": False
        }

        # Count interaction types
        for inv in session["interactions"]:
            t = inv["type"]
            analysis["interaction_types"][t] = analysis["interaction_types"].get(t, 0) + 1

        # Extract selectors from clicks
        selectors = []
        for click in session["clicks"]:
            if "selector" in click:
                selectors.append(click["selector"])
            if "react" in str(click).lower() or "angular" in str(click).lower():
                analysis["framework_hints"].append("frontend-framework")

        if selectors:
            from collections import Counter
            analysis["common_selectors"] = [s for s, _ in Counter(selectors).most_common(5)]

        return analysis


def main():
    monitor = LiveMonitor()

    print("=" * 60)
    print("BrowserOS neo Session Monitor")
    print("=" * 60)
    print(f"\nBrowserOS endpoint: {BROWSEROS_URL}")
    print(f"Sessions dir: {SESSIONS_DIR}")

    # Check health
    status = monitor.get_browser_status()
    print(f"\nBrowserOS Status: {status}")

    print("\n" + "=" * 60)
    print("READY TO RECORD")
    print("=" * 60)
    print("""
Instructions:
1. Open tabs in BrowserOS neo with job websites
2. Tell me the site name when you open a new tab
3. I will record all your interactions automatically
4. Say 'save' when done with a site
5. Say 'analyze' to see patterns extracted

Example commands:
- 'Start LinkedIn' - begin recording LinkedIn session
- 'Save session' - save current session to disk
- 'Analyze' - show patterns from current session
- 'List sessions' - show all recorded sessions
""")

    # Simple command loop
    while True:
        try:
            cmd = input("\n> ").strip()

            if cmd.lower() in ('quit', 'exit', 'q'):
                break
            elif cmd.lower().startswith('start '):
                parts = cmd.split(' ', 2)
                site_name = parts[1] if len(parts) > 1 else "unknown"
                url = parts[2] if len(parts) > 2 else "unknown"
                sid = monitor.record_site_start(site_name, url)
                print(f"✓ Recording started: {sid}")
            elif cmd.lower() == 'save':
                if monitor.current_site:
                    path = monitor.save_session(monitor.current_site)
                    print(f"✓ Saved: {path}")
                else:
                    print("✗ No active session")
            elif cmd.lower() == 'analyze':
                if monitor.current_site:
                    analysis = monitor.analyze_session(monitor.current_site)
                    print(json.dumps(analysis, indent=2))
                else:
                    print("✗ No active session")
            elif cmd.lower() == 'list':
                print("\nActive sessions:")
                for sid, data in monitor.sessions.items():
                    print(f"  - {sid}: {data['site_name']} ({len(data['interactions'])} interactions)")
            else:
                print(f"Unknown command: {cmd}")

        except KeyboardInterrupt:
            break
        except Exception as e:
            print(f"Error: {e}")


if __name__ == "__main__":
    main()
