"""
BrowserOS neo Agent Integration
Connects to BrowserOS neo for session recording and automation
"""
import json
import time
import asyncio
import requests
from datetime import datetime
from pathlib import Path

BROWSEROS_URL = "http://127.0.0.1:9020"
SESSIONS_DIR = Path("H:/session-records")

class BrowserOSAgent:
    """Agent for BrowserOS neo browser automation"""

    def __init__(self):
        self.session_id = None
        self.current_url = None
        self.interactions = []

    def health_check(self) -> dict:
        """Check BrowserOS neo status"""
        try:
            resp = requests.get(f"{BROWSEROS_URL}/health", timeout=5)
            return resp.json()
        except Exception as e:
            return {"error": str(e)}

    def navigate(self, url: str) -> dict:
        """Navigate to URL"""
        try:
            payload = {
                "action": "navigate",
                "url": url
            }
            resp = requests.post(f"{BROWSEROS_URL}/browser/action", 
                               json=payload, timeout=30)
            return resp.json()
        except Exception as e:
            return {"error": str(e)}

    def observe(self) -> dict:
        """Get current page state (elements, URLs, etc.)"""
        try:
            payload = {
                "action": "observe"
            }
            resp = requests.post(f"{BROWSEROS_URL}/browser/action", 
                               json=payload, timeout=30)
            return resp.json()
        except Exception as e:
            return {"error": str(e)}

    def screenshot(self) -> str:
        """Take screenshot"""
        try:
            payload = {
                "action": "screenshot"
            }
            resp = requests.post(f"{BROWSEROS_URL}/browser/action", 
                               json=payload, timeout=30)
            data = resp.json()
            if data.get("screenshot"):
                # Save screenshot
                screenshot_path = SESSIONS_DIR / f"screenshot_{datetime.now().strftime('%Y%m%d_%H%M%S')}.png"
                import base64
                img_data = base64.b64decode(data["screenshot"])
                with open(screenshot_path, 'wb') as f:
                    f.write(img_data)
                return str(screenshot_path)
            return ""
        except Exception as e:
            return f"Error: {e}"

    def record_interaction(self, interaction_type: str, details: dict = None):
        """Record an interaction"""
        self.interactions.append({
            "type": interaction_type,
            "details": details or {},
            "timestamp": datetime.now().isoformat()
        })

    def save_session(self, site_name: str) -> str:
        """Save session to disk"""
        session_data = {
            "site_name": site_name,
            "started": datetime.now().isoformat(),
            "interactions": self.interactions,
            "url_history": [i.get("details", {}).get("url") 
                          for i in self.interactions if i["type"] == "navigation"]
        }

        filepath = SESSIONS_DIR / f"{site_name}_{datetime.now().strftime('%Y%m%d_%H%M%S')}.json"
        with open(filepath, 'w', encoding='utf-8') as f:
            json.dump(session_data, f, indent=2)

        return str(filepath)


async def main():
    agent = BrowserOSAgent()

    print("=" * 60)
    print("BrowserOS neo Agent")
    print("=" * 60)

    # Health check
    status = agent.health_check()
    print(f"\nBrowserOS Status: {status}")

    print("""
Ready to record sessions.

Commands:
- 'navigate <url>' - Go to URL and record
- 'observe' - Get current page state
- 'screenshot' - Take screenshot
- 'save <site_name>' - Save current session
- 'quit' - Exit
""")

    while True:
        try:
            cmd = input("\n> ").strip()

            if cmd.lower() in ('quit', 'exit', 'q'):
                break
            elif cmd.startswith('navigate '):
                url = cmd.split(' ', 1)[1]
                result = agent.navigate(url)
                agent.record_interaction("navigation", {"url": url})
                print(f"Navigated: {url}")
                print(f"Result: {json.dumps(result, indent=2)[:200]}...")
            elif cmd == 'observe':
                result = agent.observe()
                print(json.dumps(result, indent=2)[:500])
            elif cmd == 'screenshot':
                path = agent.screenshot()
                print(f"Screenshot: {path}")
            elif cmd.startswith('save '):
                site = cmd.split(' ', 1)[1]
                path = agent.save_session(site)
                print(f"Saved: {path}")
            else:
                print(f"Unknown: {cmd}")

        except KeyboardInterrupt:
            break
        except Exception as e:
            print(f"Error: {e}")


if __name__ == "__main__":
    asyncio.run(main())
