{"content": "#!/usr/bin/env python3
"""
Job Site Session Recorder
Records browser sessions for automation pattern extraction
"""
import json
import time
from datetime import datetime
from pathlib import Path

SESSIONS_DIR = Path("H:/session-records")
PATTERNS_DIR = Path("D:/1-HERMES-AGENT/4_job_search/patterns")

SESSIONS_DIR.mkdir(parents=True, exist_ok=True)
PATTERNS_DIR.mkdir(parents=True, exist_ok=True)

class SessionRecorder:
    """Records browser interactions for job application automation"""

    def __init__(self, site_name: str):
        self.site_name = site_name
        self.session_id = f"{site_name}_{datetime.now().strftime('%Y%m%d_%H%M%S')}"
        self.start_time = datetime.now().isoformat()
        self.current_url = None
        self.interactions = []
        self.clicks = []
        self.types = []
        self.forms = []
        self.framework = None
        self.bot_protection = None

    def record_navigation(self, url: str):
        """Record URL change"""
        self.current_url = url
        self.interactions.append({
            "type": "navigation",
            "url": url,
            "timestamp": datetime.now().isoformat()
        })

    def record_click(self, element_data: dict):
        """Record a click interaction"""
        self.clicks.append(element_data)
        self.interactions.append({
            "type": "click",
            "element": element_data,
            "timestamp": datetime.now().isoformat()
        })

    def record_type(self, field_name: str, field_type: str, value_length: int, selector: str = None):
        """Record text input"""
        self.types.append({
            "field": field_name,
            "type": field_type,
            "length": value_length,
            "selector": selector
        })
        self.interactions.append({
            "type": "type",
            "field": field_name,
            "field_type": field_type,
            "value_length": value_length,
            "selector": selector,
            "timestamp": datetime.now().isoformat()
        })

    def record_form(self, form_data: dict):
        """Record form structure"""
        self.forms.append(form_data)
        self.interactions.append({
            "type": "form_discovered",
            "form": form_data,
            "timestamp": datetime.now().isoformat()
        })

    def save_session(self) -> str:
        """Save session to disk"""
        filepath = SESSIONS_DIR / f"{self.session_id}.json"

        data = {
            "site_name": self.site_name,
            "session_id": self.session_id,
            "start_time": self.start_time,
            "end_time": datetime.now().isoformat(),
            "current_url": self.current_url,
            "framework": self.framework,
            "bot_protection": self.bot_protection,
            "total_interactions": len(self.interactions),
            "interactions": self.interactions,
            "summary": {
                "clicks": len(self.clicks),
                "types": len(self.types),
                "forms": len(self.forms),
                "navigations": len([i for i in self.interactions if i["type"] == "navigation"])
            }
        }

        with open(filepath, 'w', encoding='utf-8') as f:
            json.dump(data, f, indent=2, ensure_ascii=False)

        return str(filepath)

    def generate_pattern_report(self) -> str:
        """Generate markdown pattern report"""
        filepath = PATTERNS_DIR / f"{self.site_name}-automation-patterns.md"

        report = f"""# {self.site_name} Automation Patterns

**Generated**: {datetime.now().strftime('%Y-%m-%d %H:%M')}
**Session ID**: {self.session_id}

## Overview
- Total interactions: {len(self.interactions)}
- Clicks: {len(self.clicks)}
- Form fills: {len(self.types)}
- Forms detected: {len(self.forms)}
- JS Framework: {self.framework or 'Unknown'}
- Bot Protection: {self.bot_protection or 'None'}

## Navigation Flow
"""
        # Add navigation history
        for inv in self.interactions:
            if inv["type"] == "navigation":
                report += f"- {inv['url']}\n"

        report += """
## Click Patterns
"""
        # Analyze clicks
        click_tags = {}
        click_texts = {}
        for click in self.clicks:
            tag = click.get("tag", "UNKNOWN")
            text = click.get("text", "")[:30]
            click_tags[tag] = click_tags.get(tag, 0) + 1
            if text:
                click_texts[text] = click_texts.get(text, 0) + 1

        report += "### By Tag\n"
        for tag, count in sorted(click_tags.items(), key=lambda x: -x[1]):
            report += f"- `{tag}`: {count}\n"

        report += "\n### Common Buttons\n"
        for text, count in sorted(click_texts.items(), key=lambda x: -x[1])[:10]:
            report += f"- **{text}**: {count} clicks\n"

        report += """
## Form Fields
"""
        if self.forms:
            for form in self.forms:
                report += f"\n### Form: {form.get('selector', 'unknown')}\n"
                for field in form.get("fields", []):
                    required = "✓" if field.get("required") else " "
                    report += f"- [{required}] {field.get('name', 'unnamed')} ({field.get('type', 'text')})\n"
        else:
            report += "*No detailed form data captured*\n"

        report += """
## Automation Recommendations
"""
        report += self._generate_recommendations()

        with open(filepath, 'w', encoding='utf-8') as f:
            f.write(report)

        return str(filepath)

    def _generate_recommendations(self) -> str:
        """Generate automation recommendations based on patterns"""
        recs = []

        # Click analysis
        if len(self.clicks) > 10:
            recs.append("- Multiple clicks needed: expect multi-step flows")

        # Form analysis
        if len(self.forms) > 0:
            recs.append(f"- {len(self.forms)} form(s) detected: use form-first approach")
            for form in self.forms:
                fields = form.get("fields", [])
                if any(f.get("file") for f in fields):
                    recs.append("- File upload required: prepare CV/Resume handling")

        # Framework detection
        if self.framework:
            recs.append(f"- Detected {self.framework}: use framework-aware selectors")

        # Bot protection
        if self.bot_protection:
            recs.append(f"- WARNING: {self.bot_protection} detected - may require human intervention")

        if not recs:
            recs.append("- Simple site structure: direct navigation should work")

        return "\n".join(recs) + "\n"


def main():
    print("=" * 60)
    print("Job Site Session Recorder")
    print("=" * 60)
    print(f"\nStorage: {SESSIONS_DIR}")
    print(f"Patterns: {PATTERNS_DIR}")
    print("\nReady to record. Open a job site and tell me the site name.")


if __name__ == "__main__":
    main()
