{"content": "#!/usr/bin/env python3
"""
Live Session Recorder
Records all browser interactions in real-time
"""
import json
import time
from datetime import datetime
from pathlib import Path

SESSIONS_DIR = Path("H:/session-records")
PATTERNS_DIR = Path("D:/1-HERMES-AGENT/4_job_search/patterns")

class LiveRecorder:
    def __init__(self, site_name: str):
        self.site_name = site_name
        self.session_id = f"{site_name}_{datetime.now().strftime('%Y%m%d_%H%M%S')}"
        self.start_time = datetime.now().isoformat()
        self.current_url = None
        self.interactions = []
        self.page_states = []

    def record_navigation(self, url: str):
        """Record URL change"""
        self.current_url = url
        self.interactions.append({
            "type": "navigation",
            "url": url,
            "timestamp": datetime.now().isoformat(),
            "page_state": self._capture_page_state()
        })
        print(f"[NAV] {url}")

    def record_click(self, element_info: dict):
        """Record click interaction"""
        self.interactions.append({
            "type": "click",
            "element": element_info,
            "timestamp": datetime.now().isoformat()
        })
        print(f"[CLICK] {element_info.get('text', element_info.get('ref', 'unknown'))}")

    def record_type(self, field_name: str, field_type: str, selector: str = None):
        """Record text input"""
        self.interactions.append({
            "type": "type",
            "field": field_name,
            "field_type": field_type,
            "selector": selector,
            "timestamp": datetime.now().isoformat()
        })
        print(f"[TYPE] {field_name} ({field_type})")

    def record_form_submit(self, form_selector: str = None):
        """Record form submission"""
        self.interactions.append({
            "type": "form_submit",
            "form_selector": form_selector,
            "timestamp": datetime.now().isoformat()
        })
        print(f"[SUBMIT] Form submitted")

    def _capture_page_state(self) -> dict:
        """Capture current page structure"""
        return {
            "url": self.current_url,
            "timestamp": datetime.now().isoformat(),
            "elements_recorded": len(self.interactions)
        }

    def save_session(self) -> str:
        """Save session to disk"""
        filepath = SESSIONS_DIR / f"{self.session_id}.json"
        data = {
            "site_name": self.site_name,
            "session_id": self.session_id,
            "start_time": self.start_time,
            "end_time": datetime.now().isoformat(),
            "current_url": self.current_url,
            "total_interactions": len(self.interactions),
            "interactions": self.interactions
        }
        with open(filepath, 'w', encoding='utf-8') as f:
            json.dump(data, f, indent=2)
        print(f"[SAVED] {filepath}")
        return str(filepath)

    def generate_pattern_report(self) -> str:
        """Generate automation patterns report"""
        filepath = PATTERNS_DIR / f"{self.site_name}-automation-patterns.md"
        report = f"""# {self.site_name} Automation Patterns

**Generated**: {datetime.now().strftime('%Y-%m-%d %H:%M')}
**Session ID**: {self.session_id}

## Overview
- Total interactions: {len(self.interactions)}
- Site: {self.site_name}
- Recording period: {self.start_time} to {datetime.now().isoformat()}

## Navigation Flow
"""
        # Extract unique URLs
        urls = set()
        for inv in self.interactions:
            if inv["type"] == "navigation":
                urls.add(inv["url"])

        for url in urls:
            report += f"- {url}\n"

        report += """
## Interaction Summary
"""
        # Count by type
        types = {}
        for inv in self.interactions:
            t = inv["type"]
            types[t] = types.get(t, 0) + 1

        for t, count in types.items():
            report += f"- {t}: {count}\n"

        with open(filepath, 'w', encoding='utf-8') as f:
            f.write(report)
        print(f"[PATTERN] {filepath}")
        return str(filepath)


def main():
    print("=" * 60)
    print("Live Session Recorder")
    print("=" * 60)
    print(f"\nStorage: {SESSIONS_DIR}")
    print(f"Patterns: {PATTERNS_DIR}")
    print("\nWaiting for browser navigation...")


if __name__ == "__main__":
    main()
